(() => {
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const world = $('#world'), scene = $('#roomScene'), char = $('#character'), pet = $('#pet');
  const toast = $('#toast'), modalBackdrop = $('#modalBackdrop'), modalContent = $('#modalContent');
  const roomNames = {living:'SALA DE ESTAR', kitchen:'COZINHA', bedroom:'QUARTO', bathroom:'BANHEIRO', garden:'JARDIM'};
  const roomColors = {living:['#e9e3d6','#b99d7d'], kitchen:['#e5e4d6','#b5a58c'], bedroom:['#e9e3e1','#ad9baa'], bathroom:['#e1e9e8','#a7b9b6'], garden:['#c9d9c2','#829c71']};
  const game = {room:'living', camera:'third', energy:84, comfort:72, actions:0, day:1, hour:9, minute:20, clothes:0, skin:0, pet:'Mel', child:false, saved:false, colors:['#e9e3d6','#b99d7d'], sound:true, activeAction:null};
  let toastTimer, swipe = null, joyPointer = null, joyOrigin = null, soundCtx;
  const say = (text) => { toast.textContent=text; toast.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>toast.classList.remove('show'),2400); };
  const save = (silent=false) => { try { localStorage.setItem('primavera-save',JSON.stringify(game)); game.saved=true; if(!silent) say('Seu cantinho foi salvo com carinho ♡'); } catch { if(!silent) say('Não foi possível salvar neste navegador.'); } };
  const load = () => { try { const s=JSON.parse(localStorage.getItem('primavera-save')); if(s){Object.assign(game,s); applyRoom(game.room,false); updateBars(); if(game.child) familyContent(); say('Bem-vinda de volta ao seu lar ♡');} } catch {} };
  const updateBars=()=>{ $('#energyBar').style.width=game.energy+'%'; $('#comfortBar').style.width=game.comfort+'%'; $('#moodText').textContent=game.energy>65?'radiante ✦':game.energy>35?'bem tranquila':'hora de descansar'; };
  function applyRoom(room, notify=true){
    game.room=room; $('#roomName').textContent=roomNames[room]; $$('.room-tab').forEach(b=>b.classList.toggle('selected',b.dataset.room===room));
    scene.className='room-scene'+(game.camera==='first'?' first-person':'');
    scene.style.setProperty('--wall',roomColors[room][0]); scene.style.setProperty('--floorc',roomColors[room][1]);
    const decor = $('.sofa'); const table=$('.coffee-table'), console=$('.console'), art=$('.art-frame'), windowEl=$('.window'), lamp=$('.lamp'), rug=$('.rug');
    if(room==='living'){ decor.style.display='';table.style.display='';console.style.display='';art.style.display='';windowEl.style.display='';lamp.style.display='';rug.style.display='';$('.plant-left').style.display='';$('.plant-right').style.display='';pet.style.display=''; }
    else if(room==='kitchen'){ decor.style.display='none';table.style.display='none';console.style.display='';console.style.width='48%';console.style.right='14%';console.style.bottom='33%';console.style.height='9%';art.style.display='';art.querySelector('span').innerHTML='home<br>cooked <i>♡</i>';windowEl.style.display='';lamp.style.display='none';rug.style.display='none';$('.plant-left').style.display='';$('.plant-right').style.display='none';pet.style.display=''; }
    else if(room==='bedroom'){decor.style.display='';decor.style.width='48%';decor.style.height='36%';decor.style.background='';table.style.display='none';console.style.display='';console.style.width='21%';console.style.right='15%';console.style.bottom='27%';console.style.height='12%';art.style.display='';art.querySelector('span').innerHTML='dream<br>softly <i>☾</i>';windowEl.style.display='';lamp.style.display='';rug.style.display='';$('.plant-left').style.display='none';$('.plant-right').style.display='';pet.style.display='';}
    else if(room==='bathroom'){decor.style.display='none';table.style.display='none';console.style.display='';console.style.width='39%';console.style.right='17%';console.style.bottom='31%';console.style.height='20%';console.style.background='linear-gradient(180deg,#f4f3ea 0 64%,#c9d8d5 65%)';art.style.display='';art.querySelector('span').innerHTML='breathe<br>in <i>✿</i>';windowEl.style.display='';lamp.style.display='none';rug.style.display='none';$('.plant-left').style.display='';$('.plant-right').style.display='none';pet.style.display='none';}
    else {decor.style.display='none';table.style.display='none';console.style.display='';console.style.width='44%';console.style.right='17%';console.style.bottom='26%';console.style.height='6%';console.style.background='linear-gradient(180deg,#8b684e,#6c503d)';art.style.display='none';windowEl.style.display='none';lamp.style.display='none';rug.style.display='none';$('.plant-left').style.display='';$('.plant-right').style.display='';pet.style.display='';}
    char.style.left=room==='garden'?'50%':'70%'; char.style.bottom=room==='garden'?'17%':'18%'; $('#actionBubble').textContent=room==='garden'?'Que ar fresquinho ☀':'Que manhã gostosa ☀';
    if(notify){ say(`Você entrou na ${roomNames[room].toLowerCase()} ✿`); playTone(440,.07); }
  }
  function playTone(freq=520,dur=.08){if(!game.sound)return;try{soundCtx ||= new (window.AudioContext||window.webkitAudioContext)();const osc=soundCtx.createOscillator(),gain=soundCtx.createGain();osc.frequency.value=freq;osc.type='sine';gain.gain.setValueAtTime(.035,soundCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,soundCtx.currentTime+dur);osc.connect(gain);gain.connect(soundCtx.destination);osc.start();osc.stop(soundCtx.currentTime+dur);}catch{}}
  const actionMessages={
    'Fazer café da manhã':['Você preparou um café da manhã quentinho ☕','Cheirinho bom tomando conta da casa!'],
    'Lavar a louça da noite':['A louça ficou brilhando ✨','Cozinha em ordem, mente tranquila.'],
    'Regar as plantas':['As plantinhas ganharam água e carinho ❀','Uma folhinha nova agradece o cuidado.'],
    'Fazer carinho na Mel':['Mel ganhou um carinho demorado e abanou o rabo ♡','Mel está feliz por ter você por perto!'],
    'Organizar a sala':['Tudo no lugar. Que sensação gostosa!','A sala ficou ainda mais aconchegante.'],
    'Limpar o chão':['Você deixou o chão limpinho ✨','Um cuidado de cada vez, e tudo floresce.'],
    'Cozinhar uma receita':['Você preparou algo delicioso com calma ♨','A cozinha ficou cheia de aromas bons.'],
    'Arrumar a cama':['A cama ficou linda e convidativa ☁','Seu quarto está pronto para uma pausa.'],
    'Dar banho na Mel':['Mel tomou um banho morninho e ficou cheirosa 🫧','Hora de secar e ganhar petiscos!'],
    'Brincar com a Mel':['Mel correu atrás do brinquedo toda feliz!','Um tempinho de brincadeira fez bem para vocês.'],
    'Alimentar a Mel':['Mel saboreou a refeição e agradeceu com o rabinho ♡','Barriguinha feliz, coração tranquilo.'],
    'Cuidar do bebê':['Um momento de carinho que vocês vão guardar ♡','O bebê está contente e bem cuidado.'],
    'Dar mamadeira':['Mamadeira quentinha, colo aconchegante 🍼','O bebê ficou satisfeito e sonolento.'],
    'Dar banho no bebê':['Banho morninho e muitas risadinhas 🫧','Um bebê limpinho e feliz!'],
    'Colocar bebê para dormir':['O bebê adormeceu no seu colo ☾','Boa noite, pequenino. Descanse bem.'],
    'Trocar roupa':['Um look novo que combina com você ♡','Prontinha para aproveitar o dia!'],
    'Cuidar do jardim':['Você cuidou do jardim com carinho ❀','Seu cantinho ficou ainda mais florido.']
  };
  function doAction(text){
    game.actions++; game.energy=Math.max(15,game.energy-(text.includes('carinho')||text.includes('Brincar')?0:4));game.comfort=Math.min(100,game.comfort+3);updateBars();
    game.activeAction=text;scene.classList.add('action');setTimeout(()=>scene.classList.remove('action'),1800);
    if(text.includes('Mel')||text.includes('bebê')||text.includes('mamadeira')){pet.style.left=(parseInt(char.style.left)||70)+'%';}
    const messages=actionMessages[text]||['Você cuidou de mais um pedacinho do seu lar ✿','Cada pequeno gesto deixa o dia mais bonito.'];
    $('#actionBubble').textContent=messages[0];say(messages[Math.floor(Math.random()*messages.length)]);playTone(590,.12);updateRoutine(text);save(true);
  }
  function updateRoutine(action){const targets=action.includes('café')?0:action.includes('louça')?1:action.includes('plant')||action.includes('jardim')?2:-1;if(targets>=0){const item=$$('.routine-item')[targets];item.classList.remove('active');item.classList.add('done');item.querySelector('i').textContent='✓';}}
  function chooseRoom(room){applyRoom(room);}
  $$('.room-tab').forEach(b=>b.addEventListener('click',()=>chooseRoom(b.dataset.room)));
  $$('.routine-item').forEach(b=>b.addEventListener('click',()=>{chooseRoom(b.dataset.room);$('.routine-item.active')?.classList.remove('active');b.classList.add('active');}));
  $$('.quick-actions button').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));
  $$('[data-action]').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));
  $$('.object-hit').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.object==='Mel'){openPet();return}openObject(b.dataset.object)}));
  $('#interactBtn').addEventListener('click',()=>{
    const acts={living:['Fazer carinho na Mel','Organizar a sala','Fazer café da manhã'],kitchen:['Lavar a louça da noite','Cozinhar uma receita'],bedroom:['Arrumar a cama','Trocar roupa'],bathroom:['Tomar um banho relaxante','Limpar o chão'],garden:['Regar as plantas','Cuidar do jardim']};
    openChoices('O que você quer fazer?',`Na ${roomNames[game.room].toLowerCase()}, escolha um momento para cuidar de você e do seu lar.`,acts[game.room].map(a=>({icon:iconFor(a),title:a,sub:'Você faz no seu tempo'})),x=>doAction(x));
  });
  function iconFor(t){return /café|Cozinhar/.test(t)?'☕':/Mel/.test(t)?'♡':/plant|jardim/i.test(t)?'❀':/cama/.test(t)?'☁':/banho/.test(t)?'♨':'⌂'}
  function openObject(name){const options=name==='Mesinha'?['Fazer café da manhã','Cozinhar uma receita']:name==='Planta'?['Regar as plantas','Cuidar do jardim']:['Organizar a sala','Limpar o chão'];openChoices(`Cuidar de ${name.toLowerCase()}`,`Escolha como quer interagir com ${name==='Planta'?'a sua planta':'esse cantinho'}.`,options.map(a=>({icon:iconFor(a),title:a,sub:'Uma atividade tranquila'})),doAction);}
  function openPet(){openChoices('Um momento com a Mel','Sua companheira está feliz de passar o dia com você.',[{icon:'♡',title:'Fazer carinho na Mel',sub:'Um carinho atrás da orelha'},{icon:'✿',title:'Alimentar a Mel',sub:'Uma refeição gostosa'},{icon:'♨',title:'Dar banho na Mel',sub:'Banho morno e toalha macia'},{icon:'⌁',title:'Brincar com a Mel',sub:'Hora do brinquedo favorito'}],doAction);}
  function openChoices(title,desc,options,onchoose){modalContent.innerHTML=`<span class="eyebrow">SEU LAR, SEU RITMO</span><h2>${title}</h2><p>${desc}</p><div class="modal-grid">${options.map(o=>`<button class="choice-card" data-choice="${o.title}"><span>${o.icon}</span><b>${o.title}</b><small>${o.sub||'Escolha esta opção'}</small></button>`).join('')}</div><button class="modal-action" id="choiceClose">Agora não</button>`;openModal();$$('[data-choice]',modalContent).forEach(b=>b.addEventListener('click',()=>{closeModal();onchoose(b.dataset.choice)}));$('#choiceClose').onclick=closeModal;}
  function openModal(){modalBackdrop.classList.add('open');}
  function closeModal(){modalBackdrop.classList.remove('open');}
  $('#modalClose').addEventListener('click',closeModal);modalBackdrop.addEventListener('click',e=>{if(e.target===modalBackdrop)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
  function openCustomize(){
    const skinColors=['#f1d0b6','#dbad8c','#bd886a','#8e5e48','#684331'],hair=['#59443a','#2e2928','#bc875d','#d5ba8e','#8d574e'],tops=['#b8c5a9','#d5b9c9','#a8c6cc','#e3c991','#d6d5e6'];
    modalContent.innerHTML=`<span class="eyebrow">DO SEU JEITINHO</span><h2>Um estilo que é seu.</h2><p>Personalize seu visual e mude sempre que sentir vontade.</p><b class="custom-label">Tom de pele</b><div class="custom-row" id="skinColors">${skinColors.map((c,i)=>`<button class="swatch ${i===game.skin?'selected':''}" style="background:${c}" data-index="${i}" aria-label="Tom de pele ${i+1}"></button>`).join('')}</div><b class="custom-label">Cabelo</b><div class="custom-row" id="hairColors">${hair.map(c=>`<button class="swatch" style="background:${c}" aria-label="Cor de cabelo"></button>`).join('')}</div><b class="custom-label">Roupa</b><div class="custom-row" id="tops">${tops.map((c,i)=>`<button class="swatch ${i===game.clothes?'selected':''}" style="background:${c}" data-index="${i}" aria-label="Roupa ${i+1}"></button>`).join('')}</div><button class="modal-action" id="styleDone">Prontinho, adorei ♡</button>`;
    openModal();$$('#skinColors .swatch').forEach(b=>b.onclick=()=>{$$('#skinColors .swatch').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');game.skin=+b.dataset.index;$('.char-head').style.background=skinColors[game.skin];$('.arm-left').style.background=skinColors[game.skin];$('.arm-right').style.background=skinColors[game.skin];});$$('#hairColors .swatch').forEach(b=>b.onclick=()=>{$$('#hairColors .swatch').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('.char-hair').style.background=b.style.background;});$$('#tops .swatch').forEach(b=>b.onclick=()=>{$$('#tops .swatch').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');game.clothes=+b.dataset.index;$('.char-body').style.background=`linear-gradient(110deg,${tops[game.clothes]},#f1eee4 54%,${tops[game.clothes]})`;});$('#styleDone').onclick=()=>{closeModal();say('Seu visual ficou lindo! ♡');save(true)};
  }
  $('#editBtn').addEventListener('click',openDecorate); $('#profileBtn').addEventListener('click',openCustomize); $('#mobileWardrobe').addEventListener('click',openCustomize);
  function openDecorate(){const colors=['#e9e3d6','#e9d8d7','#d6e5dc','#dcd5e8','#eaddbd','#c7d8df'];modalContent.innerHTML=`<span class="eyebrow">UM LAR COM A SUA CARA</span><h2>Vamos decorar?</h2><p>Escolha uma paleta suave para as paredes. Seu espaço, suas escolhas.</p><b class="custom-label">Cor das paredes</b><div class="custom-row">${colors.map(c=>`<button class="swatch ${game.colors[0]===c?'selected':''}" style="background:${c}" data-color="${c}"></button>`).join('')}</div><div class="modal-grid"><button class="choice-card" data-decor="Sofá novo"><span>🛋</span><b>Sofá novo</b><small>180 pétalas</small></button><button class="choice-card" data-decor="Planta bonita"><span>🪴</span><b>Planta bonita</b><small>45 pétalas</small></button><button class="choice-card" data-decor="Quadro delicado"><span>🖼</span><b>Quadro delicado</b><small>60 pétalas</small></button></div><button class="modal-action" id="decorDone">Ficou do meu jeito ✿</button>`;openModal();$$('[data-color]').forEach(b=>b.onclick=()=>{$$('[data-color]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');game.colors[0]=b.dataset.color;scene.style.setProperty('--wall',game.colors[0]);});$$('[data-decor]').forEach(b=>b.onclick=()=>{b.classList.toggle('chosen');say(`${b.dataset.decor} adicionado à sua lista de desejos ✿`)});$('#decorDone').onclick=()=>{closeModal();say('Sua casa ficou ainda mais aconchegante ♡');save(true)};}
  function familyContent(){if(game.child){const el=$('.family-card');if(el){el.querySelector('b').textContent='Uma família do seu jeitinho.';el.querySelector('small').textContent='Você, Mel e o bebê ♡';el.querySelector('.family-illustration').innerHTML='<span class="family-person">☺</span><span class="family-pet">🍼</span>';}}}
  $('#familyBtn').addEventListener('click',()=>{modalContent.innerHTML=`<span class="eyebrow">FAMÍLIA É O QUE VOCÊ ESCOLHE</span><h2>Seu futuro, suas escolhas.</h2><p>Seu lar é completo do jeito que você decidir. Você pode construir uma família com um bebê ou seguir uma vida tranquila com a Mel — nenhuma escolha limita sua jornada.</p><div class="modal-grid"><button class="choice-card ${game.child?'chosen':''}" id="wantBaby"><span>🍼</span><b>Quero um bebê</b><small>Novas rotinas e carinho</small></button><button class="choice-card ${!game.child?'chosen':''}" id="noBaby"><span>🐕</span><b>Por enquanto, só nós</b><small>Uma vida completa assim</small></button></div><button class="modal-action" id="familyDone">Essa é a minha escolha ♡</button>`;openModal();$('#wantBaby').onclick=()=>{game.child=true;$$('.choice-card').forEach(x=>x.classList.remove('chosen'));$('#wantBaby').classList.add('chosen')};$('#noBaby').onclick=()=>{game.child=false;$$('.choice-card').forEach(x=>x.classList.remove('chosen'));$('#noBaby').classList.add('chosen')};$('#familyDone').onclick=()=>{familyContent();closeModal();say(game.child?'Um novo capítulo começa com carinho ♡':'Uma vida completa, no seu ritmo ♡');save(true)};});
  $('#cameraBtn').addEventListener('click',()=>{game.camera=game.camera==='third'?'first':'third';$('#cameraLabel').textContent=game.camera==='third'?'3ª pessoa':'1ª pessoa';scene.classList.toggle('first-person',game.camera==='first');$('#moveTip').textContent=game.camera==='first'?'DESLIZE PARA OLHAR ↗':'DESLIZE PARA OLHAR ↗';say(game.camera==='first'?'Visão em primeira pessoa':'Visão em terceira pessoa');playTone(460);});
  $('#saveBtn').addEventListener('click',()=>save()); $('#soundBtn').addEventListener('click',()=>{game.sound=!game.sound;$('#soundBtn').style.opacity=game.sound?'1':'.45';say(game.sound?'Sons suaves ativados ♫':'Sons desativados');if(game.sound)playTone(500)});
  $('#resetDay').addEventListener('click',()=>{$$('.routine-item').forEach((b,i)=>{b.classList.toggle('active',i===0);b.classList.remove('done');b.querySelector('i').textContent='›'});game.energy=84;game.comfort=72;updateBars();say('Um novo dia, sem pressa ☀')});
  $('#helpBtn').addEventListener('click',()=>openChoices('Como aproveitar seu dia','Explore a casa usando as abas. Use o controle à esquerda para andar e arraste a cena para olhar ao redor. Toque nos objetos ou em Interagir para escolher uma atividade.',[{icon:'⌖',title:'Movimente-se',sub:'Controle virtual no canto esquerdo'},{icon:'◉',title:'Mude a câmera',sub:'Primeira ou terceira pessoa'},{icon:'▣',title:'Salve seu progresso',sub:'Use o botão no topo'}],()=>{}));
  $('#moreBtn').addEventListener('click',()=>openChoices('Seu cantinho','O que gostaria de fazer?',[{icon:'♙',title:'Mudar meu visual',sub:'Cabelo, pele e roupas'},{icon:'✎',title:'Decorar a casa',sub:'Cores e objetos'},{icon:'▣',title:'Salvar progresso',sub:'Guardar este momento'}],x=>{if(x==='Mudar meu visual')openCustomize();else if(x==='Decorar a casa')openDecorate();else save()}));
  $('#mobileRoutine').addEventListener('click',()=>openChoices('Rotina tranquila','Escolha um momento para seu dia.',[{icon:'☕',title:'Fazer café da manhã',sub:'Comece devagar'},{icon:'♡',title:'Fazer carinho na Mel',sub:'Um momento juntinhas'},{icon:'❀',title:'Regar as plantas',sub:'O jardim agradece'}],doAction));
  $('#mobileShop').addEventListener('click',openDecorate);$('#mobileMenu').addEventListener('click',()=>openChoices('Um dia no seu ritmo','Tudo que você precisa para cuidar do seu lar.',[{icon:'✎',title:'Decorar a casa',sub:'Deixe tudo com a sua cara'},{icon:'♙',title:'Mudar meu visual',sub:'Experimente um novo look'},{icon:'♡',title:'Nossa família',sub:'Suas escolhas, sempre'}],x=>{if(x.includes('decorar'))openDecorate();else if(x.includes('visual'))openCustomize();else $('#familyBtn').click()}));
  const joystick=$('#joystick'),knob=$('#joyKnob');joystick.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;const r=joystick.getBoundingClientRect();joyOrigin={x:r.left+r.width/2,y:r.top+r.height/2};joystick.setPointerCapture(e.pointerId);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function moveJoy(e){if(!joyOrigin)return;let dx=e.clientX-joyOrigin.x,dy=e.clientY-joyOrigin.y,dist=Math.hypot(dx,dy),max=18;if(dist>max){dx=dx/dist*max;dy=dy/dist*max}knob.style.transform=`translate(${dx}px,${dy}px)`;if(Math.abs(dx)+Math.abs(dy)>5){let left=parseFloat(char.style.left)||70;let rect=world.getBoundingClientRect();let move=dx/18*1.35;char.style.left=Math.max(8,Math.min(91,left+move))+'%';if(game.camera==='first'&&dy)scene.style.setProperty('--lookY',dy+'px');}}
  const endJoy=()=>{joyPointer=null;joyOrigin=null;knob.style.transform='';};joystick.addEventListener('pointerup',endJoy);joystick.addEventListener('pointercancel',endJoy);joystick.addEventListener('lostpointercapture',endJoy);
  world.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.target.closest('.room-switcher')||e.target.closest('.joystick')||e.target.closest('.interact-button'))return;swipe={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};world.setPointerCapture(e.pointerId)});
  world.addEventListener('pointermove',e=>{if(!swipe)return;const dx=e.clientX-swipe.lastX,dy=e.clientY-swipe.lastY;if(Math.abs(e.clientX-swipe.x)+Math.abs(e.clientY-swipe.y)>4)swipe.moved=true;if(swipe.moved){let left=parseFloat(char.style.left)||70;char.style.left=Math.max(8,Math.min(91,left+dx/world.clientWidth*100*.52))+'%';if(game.camera==='first'){const shift=scene.style.getPropertyValue('--lookX')||'0px';scene.style.setProperty('--lookX',(parseFloat(shift)+dx*.18)+'px');$('.back-wall').style.transform=`translate(${parseFloat(scene.style.getPropertyValue('--lookX'))}px,${dy*.12}px) scale(1.04)`;}}swipe.lastX=e.clientX;swipe.lastY=e.clientY;});
  world.addEventListener('pointerup',e=>{if(swipe?.moved&&Math.abs(e.clientX-swipe.x)>30)playTone(350,.04);swipe=null});world.addEventListener('pointercancel',()=>swipe=null);
  setInterval(()=>{game.minute+=10;if(game.minute>=60){game.minute=0;game.hour=(game.hour+1)%24}const h=String(game.hour).padStart(2,'0'),m=String(game.minute).padStart(2,'0');$('#timeLabel').textContent=`${h}:${m} · ${game.hour<12?'manhã tranquila':game.hour<18?'tarde serena':'noite aconchegante'}`;if(game.minute===0)save(true)},60000);
  load();applyRoom(game.room,false);
})();

